				storage: {
					async exists() {
						return true;
					},
					async download() {
						await db.deleteFrom("media").where("id", "=", pending.id).execute();
						return {
							body: new Response(new Uint8Array([1, 2, 3])).body as ReadableStream<Uint8Array>,
							contentType: "application/pdf",
