		});
		const storage = streamingStorage();
		let startDelete: (() => void) | undefined;
		const deleteStarted = new Promise<void>((resolve) => {
			startDelete = resolve;
		});
		let finishDelete: (() => void) | undefined;
		const allowDelete = new Promise<void>((resolve) => {
			finishDelete = resolve;
		});

