			params: { id: pending.id },
			locals: {
				emdash: {
					db,
					storage,
					handleMediaGet: (id: string) => handleMediaGet(db, id),
					handleMediaDelete: async (id: string) => {
						startDelete?.();
						await allowDelete;
						return handleMediaDelete(db, id, storage);
					},
				},
				user: {
					id: "user-1",
					email: "test@example.com",
					name: "Test User",
					role: 30,
				},
			},
		} as unknown as APIContext);
