				.selectFrom("_emdash_media_usage_reconciliations")
				.select("collection_id")
				.where("collection_id", "=", collection.id)
				.executeTakeFirst(),
		).toBeUndefined();
		expect(await usage.findSource(quarantinedSourceKey)).not.toBeNull();
	})

